#!/usr/bin/env node
/**
 * Prints, for each question it is given, THE LESSON `buscar_en_curso` LANDS ON.
 * Numbers only. Generated by running api's own tool over api's own corpus.
 *
 * WHY THIS EXISTS, and it is a house rule rather than a convenience.
 *
 * ai/tests/queries.py used to carry that column as a hand-typed dict, documented
 * as «the measured output of the real ranking over the real content, frozen». It
 * was not: measured against the real scorer it disagreed on 53 of 138 entries, and
 * the test that was supposed to protect it (`the recorded baseline still
 * reproduces`) only checked that the typed dict summed to the number the docstring
 * quoted — it compared the copy against itself and never invoked a scorer. So the
 * whole «the router beats substring counting by N points» claim was measured
 * against a column no run produces.
 *
 * A hand-typed second copy of something the code already knows is the drift bug
 * this repository has fought all the way through v3. The fix is the same one as
 * scripts/emit-lesson-index.mjs: FETCH it. This script cannot drift from
 * `buscar_en_curso`, because it calls it.
 *
 * WHAT IT MAY PRINT: a lesson number per query, and counts. No fragment, no
 * title, no prose. `lessons.technical`, `lessons.analogy`, `lesson_text.*` and
 * `labs.prompt` are all `muro: de_pago`, they are all loaded in this process to
 * score against, and NOT ONE CHARACTER of them appears in the output — the same
 * structural guarantee emit-lesson-index.mjs has, for the same reason: what
 * crosses into ai/ is integers.
 *
 * HOW IT GETS THE CORPUS WITHOUT A DATABASE. `api/src/db.ts` is swapped for
 * scripts/lib/db-memory.mjs (see scripts/lib/db-swap-loader.mjs), then
 * `api/src/seed.ts` is imported: it runs exactly as it does against Postgres and
 * every row it would have written is recorded in memory. That is api's own answer
 * to «what is in the corpus», executed rather than transcribed. The tool is then
 * imported and called for real. Neither file is modified and neither knows.
 *
 * The alternative — a replica of the scorer here — was rejected on the same
 * ground as the typed dict: a replica is a copy, a copy drifts, and the drift is
 * invisible precisely because both sides are in this repository and agree with
 * each other.
 *
 * WHOSE ACCOUNT IT MEASURES: one with every lesson open. `readableLessons()`
 * filters the corpus BEFORE the search (the paywall fix), so the baseline depends
 * on who is asking; the honest comparison for a retrieval layer is against the
 * search at its STRONGEST, which is a paid account with all twelve lessons
 * readable. `ctx.readable` is set to 1..12 and reported in the payload, so the
 * number can never be quoted without the condition it was measured under.
 *
 * Usage:
 *   echo '{"consultas":[{"q":"como lo hago menos aleatorio","lang":"es"}]}' \
 *     | node --experimental-strip-types scripts/emit-search-baseline.mjs
 *
 * Exit 0 with the baseline. Exit 1, with a reason, rather than a partial one.
 */

import { register } from 'node:module';
import { dirname, resolve } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const rel = (p) => p.slice(ROOT.length + 1);

const die = (msg) => { console.error(`emit-search-baseline: ${msg}`); process.exit(1); };

// Two dummies, for the same reason emit-lesson-index.mjs uses one: the modules
// below refuse to load without them, and nothing here connects or signs anything.
// Narrower than NODE_ENV=development, which would also mint a real session key.
process.env.DATABASE_URL ??= 'postgres://search-baseline-emitter-never-connects/none';
process.env.JWT_SECRET ??= 'search-baseline-emitter-never-signs-a-session-token';
// content.ts now crosses the same closed data client as production. The emitter
// still has no database: intercept only its three read operations and answer
// them from the seeded in-memory corpus below. This keeps the measured scorer
// real without smuggling a Postgres fallback into runtime API code.
process.env.DATA_URL ??= 'http://127.0.0.1:8788';
process.env.DATA_SECRETO ??= 'search-baseline-emitter-data-secret';
// api/src/seed.ts creates demo accounts only when this is '1'. It must not be.
if (process.env.SEED_DEMO_USERS === '1') {
  die('SEED_DEMO_USERS=1 is set. This script imports the seed to READ the corpus; '
      + 'it must not be asked to hash passwords for demo accounts.');
}

// ---------------------------------------------------------------- the input
const stdin = await new Promise((ok, no) => {
  let buf = '';
  process.stdin.setEncoding('utf8');
  process.stdin.on('data', (c) => { buf += c; });
  process.stdin.on('end', () => ok(buf));
  process.stdin.on('error', no);
});
if (!stdin.trim()) {
  die('nothing on stdin. It expects {"consultas":[{"q":"…","lang":"es"}, …]} — the query '
      + 'list stays in ai/tests/queries.py, which is the only copy of it.');
}
let asked;
try {
  asked = JSON.parse(stdin);
} catch (err) {
  die(`stdin is not JSON (${err.message}).`);
}
const consultas = asked?.consultas;
if (!Array.isArray(consultas) || !consultas.length) {
  die('the payload has no non-empty «consultas» array. Refusing to print a baseline over '
      + 'nothing: an empty comparison passes every comparison.');
}
for (const c of consultas) {
  if (typeof c?.q !== 'string' || !c.q.trim()) die(`a «consultas» entry has no query: ${JSON.stringify(c)}`);
  if (c.lang !== 'es' && c.lang !== 'en') die(`«${c.q}» has lang ${JSON.stringify(c?.lang)}; expected «es» or «en».`);
}

// ------------------------------------------------------- the corpus, executed
register(new URL('./lib/db-swap-loader.mjs', import.meta.url));

const load = async (path) => {
  try {
    return await import(pathToFileURL(path).href);
  } catch (err) {
    die(`could not import ${rel(path)}:\n  ${err.message}\n`
        + `This script needs Node's type stripping. On Node 22 run it as:\n`
        + `  node --experimental-strip-types scripts/emit-search-baseline.mjs`);
  }
};

const MEMORY = resolve(ROOT, 'scripts/lib/db-memory.mjs');
const SEED = resolve(ROOT, 'api/src/seed.ts');
const CONTENT = resolve(ROOT, 'api/src/tools/content.ts');
const ACCESS = resolve(ROOT, 'api/src/tools/access.ts');

const memory = await load(MEMORY);

// The seed is a script: it prints a summary line and would land in the middle of
// this file's JSON. Its stdout is swallowed for the duration, and only its stdout —
// anything it writes to stderr still shows, because a warning from the corpus
// loader is exactly what somebody debugging a wrong number needs to see.
const realWrite = process.stdout.write.bind(process.stdout);
process.stdout.write = () => true;
try {
  await load(SEED);
} finally {
  process.stdout.write = realWrite;
}

const lessons = memory.tables['lessons'] ?? [];
const texts = memory.tables['lesson_text'] ?? [];
const labs = memory.tables['labs'] ?? [];
if (!lessons.length || !texts.length || !labs.length) {
  die(`importing ${rel(SEED)} left the corpus incomplete: ${lessons.length} lesson(s), `
      + `${texts.length} lesson text(s), ${labs.length} lab(s). A baseline scored against `
      + `an empty corpus is a table of zeroes that looks like a measurement.`);
}

const realFetch = globalThis.fetch;
globalThis.fetch = async (input, init = {}) => {
  const url = typeof input === 'string' ? input : input instanceof URL ? input.href : input.url;
  if (!url.startsWith(`${process.env.DATA_URL}/v1/op`)) return realFetch(input, init);
  let body;
  try { body = JSON.parse(String(init.body ?? '{}')); } catch { return new Response(JSON.stringify({ error: 'bad_request' }), { status: 400 }); }
  const args = body.args ?? {};
  const project = (rows, names) => rows.map((row) => Object.fromEntries(names.map((name) => [name, row[name] ?? null])));
  let rows;
  if (body.op === 'lesson.search_corpus') {
    rows = project(lessons, ['n', 'eyebrow', 'title', 'summary', 'math_cap', 'technical', 'analogy']);
  } else if (body.op === 'lesson_text.by_lang') {
    rows = project(texts.filter((row) => String(row.lang) === String(args.lang)), ['lesson_n', 'technical', 'analogy']);
  } else if (body.op === 'lab.prompts') {
    rows = project(labs.sort((a, b) => Number(a.lesson_n) - Number(b.lesson_n) || Number(a.idx) - Number(b.idx)), ['id', 'lesson_n', 'prompt']);
  } else {
    return new Response(JSON.stringify({ error: 'unknown_operation' }), { status: 404, headers: { 'content-type': 'application/json' } });
  }
  return new Response(JSON.stringify({ operation: body.op, rows, affected: rows.length }), { status: 200, headers: { 'content-type': 'application/json' } });
};

const access = await load(ACCESS);
const total = access.TOTAL_LESSONS;
if (!Number.isInteger(total) || total <= 0) {
  die(`api/src/tools/access.ts does not export a usable TOTAL_LESSONS (got ${JSON.stringify(total)}).`);
}
if (lessons.length !== total) {
  die(`the seed wrote ${lessons.length} lesson(s) and access.ts says there are ${total}. `
      + `A payload that disagrees with itself cannot be compared against anything.`);
}

const content = await load(CONTENT);
const search = content?.CONTENT_TOOLS?.buscar_en_curso;
if (typeof search?.fn !== 'function') {
  die(`api/src/tools/content.ts does not export CONTENT_TOOLS.buscar_en_curso.fn. That IS the `
      + `baseline; there is nothing to measure without it.`);
}

// ------------------------------------------------------------- the measurement
// Every lesson open: see the header. `readable` short-circuits readableLessons(),
// which is what keeps `users` out of this process entirely — there is no account
// here, and no query against one.
const readable = new Set(Array.from({ length: total }, (_, i) => i + 1));

const baseline = {};
const hits = {};
let sinResultado = 0;
for (const { q, lang } of consultas) {
  const ctx = { userId: 0, lang, turn: 1, readable };
  let out;
  try {
    out = await search.fn(ctx, { consulta: q });
  } catch (err) {
    die(`buscar_en_curso threw on «${q}» (${lang}): ${err.message}`);
  }
  if (out?.error) die(`buscar_en_curso refused «${q}» (${lang}): ${out.error}`);
  const top = Array.isArray(out?.resultados) ? out.resultados[0] : undefined;
  const n = top?.leccion;
  if (n === undefined) {
    // A real answer, and one the caller must be able to see: the substring scorer
    // finding NOTHING is the failure the concept map exists for. `null`, never a
    // silent 0 and never a guess.
    baseline[q] = null;
    hits[q] = 0;
    sinResultado++;
    continue;
  }
  if (!Number.isInteger(n) || !readable.has(n)) {
    die(`buscar_en_curso answered lesson ${JSON.stringify(n)} for «${q}», which is not one of `
        + `the ${total} lessons it was allowed to search.`);
  }
  baseline[q] = n;
  hits[q] = Number(out.encontrados) || 0;
}

if (Object.keys(baseline).length !== consultas.length) {
  die(`asked ${consultas.length} question(s) and produced ${Object.keys(baseline).length} `
      + `answer(s) — the query list has a duplicate, so some answer overwrote another.`);
}

console.log(JSON.stringify({
  source: 'api/src/tools/content.ts (buscar_en_curso.fn) over api/src/seed.ts + api/src/content.ts',
  read_by: 'import and CALL — see the header of scripts/emit-search-baseline.mjs',
  publico: 'lesson numbers and counts only. The corpus is loaded in this process to score '
    + 'against and no character of it is printed: nothing behind `muro: de_pago` can reach ai/.',
  medido_para: `una cuenta con las ${total} lecciones abiertas (readableLessons filtra antes de buscar)`,
  corpus: {
    lecciones: lessons.length,
    textos: texts.length,
    labs: labs.length,
    idiomas: [...new Set(texts.map((t) => String(t.lang)))].sort(),
  },
  consultas: consultas.length,
  sin_resultado: sinResultado,
  leccion: baseline,
  encontrados: hits,
}, null, 2));
